# 🟡 中风险：Flag 变更直接影响线上功能行为
apiVersion: v1
kind: ConfigMap
metadata:
  name: feature-flags-definitions
  namespace: platform-system
  labels:
    app.kubernetes.io/name: feature-flag-service
  annotations:
    kudig.io/flag-owner: "product-team"
data:
  flags.json: |
    {
      "flags": {
        "new-checkout-flow": {
          "state": "ENABLED",
          "variants": {
            "on": true,
            "off": false
          },
          "defaultVariant": "off",
          "targeting": {
            "if": [
              {"in": ["@user.email", ["vip@example.com", "beta@example.com"]]},
              "on",
              {
                "if": [
                  {"<": [{"var": "bucket"}, 15]},
                  "on",
                  "off"
                ]
              }
            ]
          }
        },
        "ai-recommendation": {
          "state": "ENABLED",
          "variants": {
            "v2-model": "model-v2",
            "v1-model": "model-v1",
            "disabled": "none"
          },
          "defaultVariant": "disabled",
          "targeting": {
            "if": [
              {"==": [{"var": "region"}, "cn-north"]},
              {
                "if": [
                  {"<": [{"var": "bucket"}, 30]},
                  "v2-model",
                  "v1-model"
                ]
              },
              "v1-model"
            ]
          }
        },
        "maintenance-mode": {
          "state": "DISABLED",
          "variants": {
            "on": true,
            "off": false
          },
          "defaultVariant": "off"
        }
      }
    }
